                 }

@@ -1087,7 +1075,7 @@ static int getnameinfo_done(sd_resolve_query *q) {
         assert(q->getnameinfo_handler);

         errno = q->_errno;
-        h_errno= q->_h_errno;
+        h_errno = q->_h_errno;

