static void complete_query(asyncns_t *asyncns, asyncns_query_t *q) {
        assert(asyncns);
        assert(q);
        assert(!q->done);

        q->done = 1;

        if ((q->done_prev = asyncns->done_tail))
                asyncns->done_tail->done_next = q;
        else
                asyncns->done_head = q;

        asyncns->done_tail = q;
        q->done_next = NULL;
}

